[90469] = {
  "9046918080NPCUnknown0NPCUnknown00",
  "Wowhead050Carry on, my wayward son There'll be peace when you are done Lay your weary head to rest Don't you cry no more",
  "Wowhead050Very small NPC. Located at 69.70, 26.55",
  "Wowhead050Almost impossible to see until you're right on top of her. Additionally, she's not IN Dreth'mar Cavern, she's just outside the entrance. Strangely, the game doesn't seem to do the usual thing of marking the NPC with the yellow/ grey circle to indicate the person you need to find. For people without co-ords: the waterfall and the little covered bridge will be to your right as you face the cliffs. When you're facing the enormous mushroom, fly up one level directly behind it (not to the top of the mountain, about halfway up the mushroom) and you should see Kuri right in front of you.",
},

[90470] = {
  "9047018080NPCUnknown0NPCUnknown00",
  "Wowhead050If you think there's no more skyglass available, make sure you went upstairs. In the last room on the right, there is a ramp on the right side where you will find the additional skyglass.",
  "Wowhead050When you stumble upon large clusters of skyglass that you can't click on, use the extra action button to summon Kuri to gather them for you.",
  "Wowhead050Cave entrance is 69.9, 26.7",
  "Wowhead050This is snail guano, right? Must be snail guano.",
  "Wowhead050Will bug out unless you actually kill the mobs it spawns, making it really annoying when you're just trying to finish a dumb quest in a dumb zone.",
  "Wowhead050You can't pick up the clusters of Skyglass, instead, stand in the middle of the pile and blow the whistle ability that shows up above your action bars. Warning: Will summon a monster, but the girl will pick up the shards and up your % of completion. Also: Completing this mini quest won't get you the mount you're after...it'll take some more work. Last edited by Watchtower on 2026/04/05 (Patch 12.0.1)",
},

