[90482] = {
  "9048218080NPCUnknown0NPCUnknown00",
  "Wowhead050The Clinging Depthsroot grows under the water with the other ingredients you need to gather. It is a two minute buff that gives you water breathing and 125% swim speed. The buff doesn't stack if you eat more than one, but it is pretty common in the area, so you can eat more as needed. Last edited by Zinovia on 2026/03/15 (Patch 12.0.1)",
},

[90486] = {
  "9048618080NPCUnknown0NPCUnknown00",
  "Wowhead050FYI you don't click on the Kelp on the ground - just walk on top of it and jump on it 3 times.",
  "Wowhead050After gathering everything, return to Gushu and the eels aren't in your bags they're on the ground and you just click on them at / way 47.09, 24.55 . I was almost gonna leave and kill more eels. Last edited by Braveharth on 2026/03/28 (Patch 12.0.1)",
},

[90493] = {
  "9049318080NPCUnknown0NPCUnknown00",
  "Wowhead050Don't worry when you have to choose between Sin'dorei Honor Stone and Diamond Honor Stone , since you can buy more copies of both of them from Sathren Azuredawn .",
  "Wowhead050For some reason, Arator had moved. Arator at 49,68 had no new quests for me, but Arator at 47,69 (small wrecked house down the hill) had this quest to pick up.",
},

[90494] = {
  "9049418080NPCUnknown0NPCUnknown00",
  "Wowhead050\"I'll keep guard here. Of this empty building. Where you've already killed all the bad guys. Over here. Away from danger. Stop it, I'm a hero. Just go do your thing and I'll guard this... cozy little shack here.\"",
  "Wowhead050Secretary Faloria is at 47,68 in case you were like me and forgot to loot the key and the quest is no longer showing up on your map. Loot the key and then open the small chest in the same room. Congrats! Quest complete. Last edited by AnesidoraDH on 2026/02/26 (Patch 12.0.1)",
  "Wowhead050so I had to kill Faloria before I got credit for finding Umbric, at which point I had to wait for her to respawn to kill her again for quest credit",
  "Wowhead050If you're missing the key you have forgotten to loot Secretary Faloria",
  "Wowhead050I arrived as someone else was doing secretary, joined in, got loot but no credit.",
},

[90509] = {
