[90553] = {
  "9055318080NPCUnknown0NPCUnknown00",
  "Wowhead050Got this quest at level 83, mobs are level ? elites. Really?",
  "Wowhead050lvl 90 elite with 700k+ hp lol",
  "Wowhead050Hard to do solo. Have to do it in a group or plan your pull carefully. They hit like a truck. Last edited by Ronin2420 on 2026/03/27 (Patch 12.0.1)",
  "Wowhead050When doing Blessing of Freedom pick up Leave Ashes in Your Wake & Executing the Blades (If you're Horde, anyway). (Yes, I stole this comment, but added hyperlinks. You're welcome)",
  "Wowhead050I leveled from 80 to 90 with Archaeology before I now started questing in Midnight. So I have still my old TWW lvl 80 HC Raidgear on with ilvl 148. But the quest mobs here are lvl 90 Elite. Holy moly. I got wrecked to hell. Last edited by Flanell 10 days ago (Patch 12.0.5)",
},

[90554] = {
  "9055418080NPCUnknown0NPCUnknown00",
  "Wowhead050When doing Blessing of Freedom pick up Leave Ashes in Your Wake & Executing the Blades (If you're Horde, anyway). (Yes, I stole this comment, but added hyperlinks. You're welcome)",
  "Wowhead050You would \"destroy\" the same stuff twice if you're doing Death to Twilight too.",
},

[90555] = {
  "9055518080NPCUnknown0NPCUnknown00",
  "Wowhead050Crusader Whitney is on the altar where her marker is, if anyone else is confused and doesn't see a cage :)",
  "Wowhead050Don't forget to pick up \"Leave Ashes in Your Wake\" and \"Executing the Blades\" before you head in. Otherwise, doing this quest as a fresh 90 was a pain in the ass. The addition of the two paladin NPC's is quite helpful. Last edited by Guadah on 2026/02/27 (Patch 12.0.1)",
  "Wowhead050All three of these quests are absolute BS... and I don't mean blacksmithing. Not only are all the mobs elites with massive health, but you have to kill 15 of them. And how in the hell are you traveling with two other paladins who can't even heal or do any damage? FFS, blizz, you're stupid.",
  "Wowhead050Why does Blizzard hate their playerbase? What an absolutely ridiculous quest.",
  "Wowhead050When doing Blessing of Freedom pick up Leave Ashes in Your Wake & Executing the Blades (If you're Horde, anyway). (Yes, I stole this comment, but added hyperlinks. You're welcome) Last edited by walkerius on 2026/03/15 (Patch 12.0.1)",
  "Wowhead050Some of the cages are a bit finicky and have a sweet spot. You may need to move your cursor around until you find it. For a sec, I thought the cultists had to drop a key or something.",
  "Wowhead050There is not enough CC that any character can do to survive this with a fresh 90. Mobs are packed together, so you get swarmed by 3 or 4 at a time. The paladins along with you do not do enough damage or take ANY aggro from you, so expect to die unless you are a tank.",
},

