[91386] = {
  "9138618080NPCUnknown0NPCUnknown00",
  "Wowhead050You just need to drop down from the first floor. All the items you throw (fetch) are on the ground floor.",
  "Wowhead050The items are found in the building with the Jewelcrafting Trainer / way 48.93 54.17",
  "Wowhead050I'm very confused... Why in the world is this gaggle of Pushy Paladin s lining up at Solwin Brightstitch 's Tailoring shop? Paladins wear Plate, and Tailors don't make Plate armor! And based on his comment about \"Thalassian craftsmanship,\" I doubt he's just making them a bunch of Alliance tabards or something... Perplexing.",
  "Wowhead050This quest leads to a questline which rewards Pattern: Silvermoon Curtains .",
  "Wowhead050This quest becomes available after completing the main intro quest to Silvermoon, \"Paved In Ash\".",
},

[91388] = {
  "9138818080NPCUnknown0NPCUnknown00",
  "Wowhead050\"Weakened\" in this case means kill the Engorged Silk Wyrm , it then turns friendly, and you can use the quest item on the mob.",
  "Wowhead050What a fun little jab of a quest by Blizzard pointed at PETA. They've still got it .",
  "Wowhead050Don't pull too many at once ! You only have about 10 seconds after they turn green during which you can extract the mana silk, after which they will just fly away and disappear. I pulled 4 of them at once, got them all down / green within just a few seconds of each other, but only managed to extract silk from 2 of them, while the other 2 flew away. It's BS, especially considering the quest text doesn't say anything about \"needing to extract the silk quickly because they're finicky\" or anything. =_=",
},

