[91403] = {
  "9140318080NPCUnknown0NPCUnknown00",
  "Wowhead050The drop rate on these is atrocious..",
  "Wowhead050Another chance for those to experience vanilla drop rate!",
  "Wowhead050I swear these were dropping in 2s, now the frogs just drop 1. As if the abyssmal drop rate wasn't enough.",
  "Wowhead050The quest area is small, and there aren't many frogs to kill. But there seems to be a group of four around coords 37, 27, with a few solo/ paired frogs nearby. They also seem to re-spawn slow, so that might have impacted how many mobs I saw.",
},

