[91406] = {
  "9140618080NPCUnknown0NPCUnknown00",
  "Wowhead050The last clue is upstairs in the hut. Easiest just to fly up.",
  "Wowhead050Not seeing this questline anywhere. It is the last questline I needed for the zone.",
  "Wowhead050On beta, this quest is inconsistent on when it's up. I've been running the same leveling route a few times with a friend and sometimes it's there, sometimes it isn't (we always look at the same time in the campaign if it's triggered). We had an instance where it was up for my friend and not for me. Bug report was submitted but no idea what the pre-requisite is / if there is any",
  "Wowhead050This questline becomes available after doing Den of Nalorakk: A Taste of Vengeance",
},

[91407] = {
  "9140718080NPCUnknown0NPCUnknown00",
  "Wowhead050If you don't see the extra action button, dismount.",
  "Wowhead050Not sure if there's a different quest chain if you didn't do certain quests in the zone but Halazzi's Hunt happens between this quest and the next two, A Most Vile Venom and Probable Paralytic .",
  "Wowhead050After dismounting to use the extra action button, you can, and should, do the spider part mounted. Last edited by Ophilla on 2026/03/08 (Patch 12.0.1)",
  "Wowhead050Reloading was the only way I got it to work.",
},

