[91411] = {
  "9141118080NPCUnknown0NPCUnknown00",
  "Wowhead050The entrance to where you turn in the quest is at 39.74, 23.18",
  "Wowhead050Quest item drops off Vordaza , the second boss in the Maisara Caverns dungeon.",
  "Wowhead050I did the dungeon in Mythic for the second time this week (just for practise) and the shell did not drop :( So if you have already done Mythic, do it on another difficulty. Last edited by Melandroso on 2026/03/15 (Patch 12.0.1)",
  "Wowhead050Bugged somehow in storyline. Had to do dungeon twice. So start from the quest Far from the Hinterlands.",
  "Wowhead050Where's is the quest giver to assign the follower dungeon? Cant find him",
  "Wowhead050Blizzard really needs to fix the Up/ Down height indicating arrow for this quests return since it doesn't indicate that it's far below you and makes you think it's under the hut. Last edited by Pandadood on 2026/03/21 (Patch 12.0.1)",
  "Wowhead050Since the quest item drops directly from the second boss, you need to do this on anything other than m+ to complete this quest.",
},

[91412] = {
  "9141218080NPCUnknown0NPCUnknown00",
  "Wowhead050Speaking to Shadra after she hatches, she offered me three dialogues. Two of them I believe to be triggered from previous completed questlines in the Hinterlands and Ardenweald. I am unsure if the Hinterlands trigger was from Cataclysm or Classic as I did both. Me : Do you remember me from the Hinterlands? Shadra : Yes... collecting my venom for some nefarious purpose, weren't you. I will let it slide, for now & Me : Do you rememeber me from Ardenweald? Shadra : Of course. You aided me in Ardenweald to be reborn. We are forever allies, Maw Walker",
},

