[91560] = {
  "9156018080NPCUnknown0NPCUnknown00",
  "Wowhead050I had an issue where the scouts had no dialog in their window and I couldn't cure them. I went back to the quest giver and there was an additional quest I had missed, Calculated Culling. After picking that up the scouts worked as expected.",
