[91628] = {
  "9162818080NPCUnknown0NPCUnknown00",
  "Wowhead050If you are like me and trying to find them nearby, they are in Silvermoon. Fly away and find them in the city. Last edited by vapocalypse on 2026/03/03 (Patch 12.0.1)",
  "Wowhead050In Silvermoon City Magisters: Magistrix Bloodflame 33, 51 Blood Knights: Knight-Lord Sunguard 44.63 , 71.97 Farstriders: Ranger-Captain Dawnfletch 24, 71 Traders: Vyrin the Supplier 52.79, 63.3 Last edited by Woofus on 2026/03/10 (Patch 12.0.1)",
  "Wowhead050You are looking for Ranger-Captain Dawnfletch , but for this quest, she is in Silvermoon City at 24, 71.",
  "Wowhead050Quest seems bugged. I'm at rep 9 and he doesn't have it.",
  "Wowhead050I can't seem to invite any of those NPCs, is there a known bug?",
},

[91629] = {
  "9162918080NPCUnknown0NPCUnknown00",
  "Wowhead050Who to invite? Here’s a list of items you can get from them. MAGISTERS - Apprentice Diell Ensemble: Magister's Elegant Regalia Ensemble: Magister Dignitary's Trappings Ensemble: Magister Socialite's Attire Formula: Animated Sin'dorei Pick Gentle Floating Planter (decor) Sunlit Glass Mirror (decor) Flicker (companion) BLOOD KNIGHTS - Armorer Goldcrest Ensemble: Blood Knight's Elegant Regalia Ensemble: Blood Knight Dignitary's Trappings Ensemble: Blood Knight Socialite's Attire Formula: Animated Sin'dorei Hammer Rack of Silvermoon Arms (decor) Blood Knight Recruit's Shield (shield) Blood Knight Champion's Tabard (tabard) FARSTRIDERS - Ranger Allorn Ensemble: Farstrider's Elegant Regalia Ensemble: Farstrider Dignitary's Trappings Ensemble: Farstrider Socialite's Attire Technique: Sin'dorei Phoenix Quill Farstrider's Comfy Cushion (decor) Gilded Lightwood Wardrobe (decor) Farstriders Quiver (back) SHADES OF THE ROW - Neriv Ensemble: Pilfered Elegant Regalia Ensemble: Pilfered Dignitary's Trappings Ensemble: Pilfered Socialite's Attire Formula: Self-Pouring Thalassian Sunwine Murder Row Wine Decanter (decor) Crimson Lightwood Privacy Screen (decor) Gilded Sunlance (polearm) Last edited by Marinoco 21 days ago (Patch 12.0.5)",
  "Wowhead050I guess every quest reward is going to be house garbage from now on.",
  "Wowhead050At rep 9 and he doesnt have a quest to accept.",
},

