[91805] = {
  "9180518080NPCUnknown0NPCUnknown00",
  "Wowhead050This quest name is a bit misleading. There are Heartwisp fronds located at the TOP of the mesas in this area. Not in the small caves. You can loot 2-3 fronds per node to complete the quest fairly efficiently.",
  "Wowhead050You have to loot plants on top.",
  "Wowhead050Just a bunch of random plants growing on top of a hill that just so happen to have some random mob hanging out RIGHT beside every single random plant, and nowhere else in between.",
},

