[91828] = {
  "9182818080NPCUnknown0NPCUnknown00",
  "Wowhead050Letter is behind Valeera, on the crate.",
  "Wowhead050Appears to be locked behind lvl 90, no matter your status in the quest chain. You cannot complete Sojourner of Eversong Woods or The Crimson Rogue achievements to finish the zone, until lvl 90.",
  "Wowhead050\"I left an extremely tiny and hard-to-see yellow clickable item on a yellow crate in a large room with a bunch of yellow crates.\"",
  "Wowhead050I've completed steps 1-7. including No Loose Ends, however, step 8. A Favor for the Lion is not being offered by Valeeta Sanguinar. I am lvl 90 and have completed Sojourner of Eversong Woods. Anyone have any ideas?",
  "Wowhead050The animation of Anduin talking head is quite reminiscent of a game from 1995. The picture, the moves ...",
},

