[91968] = {
  "9196818080NPCUnknown0NPCUnknown00",
  "Wowhead050There was no clutter to remove, but you can just place something (click Edit House, click an item and place it) and instantly remove it. You can do the same item four times, you won't lose it.",
  "Wowhead050In case you're an idiot like me, the tutorial shows you on the right side of the screen that selecting an already placed item and pressing \"R\" will remove it. Last edited by podnov on 2025/12/02 (Patch 11.2.7)",
  "Wowhead050Am I supposed to use Cleanup Mode to get rid of items? When I enter Edit House mode to do this, only Decorate Mode is available. Cleanup Mode is greyed out with the message \"not available while in the tutorial\". But I'm also not seeing how I can progress/ cancel the tutorial. The only quest that I have in the Neighborhood category is this one, and there's no buttons or such around on the Housing Dashboard that say anything about the tutorial. Edit: In theory, you can use \"r\" to remove a selected decor item, but it might not work for you. It didn't work for me, because it was apparently trying to activate a spell on my Action Bar 5 Button 9, which it couldn't because \"Can't do that while silenced\". I rebound Remove Decor to an otherwise unused key and it worked properly. Last edited by tale on 2025/12/03 (Patch 11.2.7)",
  "Wowhead050This quest was bugged for me and I couldn't progress (live version 11.2.7). I tried re-logging and then abandoning it, but then it wouldn't restart it since there is no quest giver/ starting NPC involved. It's just an auto-start upon logging in when you have housing available. Here's the fix: Very random but the way to restart it is to go back inside your house and restart the tutorial. Once you do, the quest will pop back into your log so you can continue progressing. Hope this helps! Last edited by Bigpurm on 2025/12/03 (Patch 11.2.7)",
  "Wowhead050I was stuck, before I realised that I had (R) = Remove Item bound to a spell. After I changed my keybind the problem was solved, and it was easy peasy. Just place four items and removed them again. Anything counts :) Last edited by Bellemora on 2025/12/06 (Patch 11.2.7)",
  "Wowhead050So in the infinite wisdom of Blizzard, now we have to redo my keybinds to use the house interface (yes there is sarcasm behind that question)? That should have been coded better. Whenever you get the UI for the house you should be avoiding the regular keybinds or it should be coded for the system to recognize a separate environment.",
  "Wowhead050For anyone stuck on this quest because \"Cleanup Mode\" is greyed out while in the tutorial, you don't need Cleanup Mode. Just stay in Decorate Mode and click any item in the room (or place some first) and then press \"R\". This will delete the selected decor ; do it 4 times to complete the quest.",
  "Wowhead050Even if no spells or items are bounded to the keybind, if the keybind is bound to a slot on your action bar at all, it will conflict with the decoration keybinds. You must unbind from your action bars in order to get the decoration/ removal to work.",
  "Wowhead050I need to unbind my R key to remove decor? edit: it seems if you turn off elvui the keybinds work Last edited by mRshykid on 2025/12/25 (Patch 11.2.7)",
  "Wowhead050Previous: Home at Last Next: Time to Decorate Last edited by Eillesthis on 2026/02/22 (Patch 12.0.1)",
},

[91969] = {
  "9196918080NPCUnknown0NPCUnknown00",
  "Wowhead050I'm not sure what the issue is but it's not completing for me. It shows up in both my Alliance and Horde quest logs. Both characters have placed multiple decor items inside and out. I'm 99% sure that dropping/ re-acquiring the quest and then completing it immediately will probably work.",
  "Wowhead050Previous: Welcome Home Next: Feathering the Nest Last edited by Eillesthis on 2026/02/22 (Patch 12.0.1)",
},

[91972] = {
  "9197218080NPCUnknown0NPCUnknown00",
  "Wowhead050If you see a group of Diseased Flayer to the right after talking to Bloodguard Nelric and accepting the assignment, do not walk over and kill them! Stand next to Bloodguard Nelric and wait for them to come over. I got stuck in an infinite loop of mobs only spawning there and not making any progress. After killing some adds on the right, some will come from straight ahead, and eventually a Reanimated Colossus will come running in from the left. Killing the Reanimated Colossus will complete the quest and make it ready to turn in.",
  "Wowhead050Bloodguard Nelric literally just solos the mobs alone",
},

[91974] = {
  "9197418080NPCUnknown0NPCUnknown00",
  "Wowhead050There should be an item in your bags called Holy Sunfire. It looks like a yellow bottle. Use it on the enemies in this area.",
  "Wowhead050The item will only work if the game says you're in Sanctum of the Moon. There are some spots there that say Eversong Woods, so if you're having issues check the location above the map.",
  "Wowhead050If your Holy Sunfire quest item is unusable, check if you also have the Dangerous Showpieces quest active (quest from Shades of the Row). Since the Twilight Weaponry quest item drops from the same humanoid mobs that are the target for this quest, you will not be able to use the Holy Sunfire until you have finished collecting the weaponry by killing the mobs yourself. You will also see that you won't be getting progress on this quest without using the item. Annoying.",
  "Wowhead050Feels like Lights version of Culling of Stratholme",
},

[91976] = {
  "9197618080NPCUnknown0NPCUnknown00",
  "Wowhead050If you're wondering why you're not getting credit for killing quest mobs, make sure you're not killing quest mobs for a world quest happening to overlap this quest's objective area.",
},

