},

[92000] = {
  "9200018080NPCUnknown0NPCUnknown00",
  "Wowhead050I talk to the 6th and last one and nothing happened. I have tried to leave the area, to log out and back in. I have not tried to abandon and retake the quest. Ok tried to abandon too. :-D When I flow back I saw there were more npc on the other side of the pillar. (I started where I first tried and one of them didn't repond - but now I had more to talk to). Last edited by Shardsy on 2026/03/25 (Patch 12.0.1)",
},

