[92006] = {
  "9200618080NPCUnknown0NPCUnknown00",
  "Wowhead050If anyone's on this quest and the vendors aren't there, just a bunch of purple fire where they should be... it's due to a questline that's a part of the campaign. The vendors phased in once I completed \"The Missing Magister\" quest",
  "Wowhead050All found in Tranquillien: Bloodthistle Brandy Master Chef Mouldier / way 47.66 67.75 Mana Burner Eralan / way 48.84 65.53 Sun-Kissed Tranquilla Inn Keeper Kalarin / way 48.96 68.53",
},

[92021] = {
  "9202118080NPCUnknown0NPCUnknown00",
  "Wowhead050You would pick this quest up at around 37,72 (just northwest of the Windrunner Spire dungeon, in Eversong Woods) but bear in mind if you can't see the questgiver yet it's because you need to further yourself along in the campaign first. I was at level 83 and couldn't find it until I got through more of my campaign, and later picked it up, still at level 83. While getting Sojourner, know that campaign progress is needed as is level requirements. Paladin Rescue for example requires level 90. Last edited by Hollyleaves on 2026/02/27 (Patch 12.0.1)",
  "Wowhead050Talandra's Rose ? Last edited by renteura on 2026/02/27 (Patch 12.0.1)",
  "Wowhead050This and A Venomous Vocation to start the Flowers for Amalthea Sojourner chapter require completion of The Missing Magister quest. The Midnight account-wide achievement unlocks this as well. Last edited by Barovian on 2026/02/27 (Patch 12.0.1)",
},

[92022] = {
  "9202218080NPCUnknown0NPCUnknown00",
  "Wowhead050Prioritize Elder Mournbat, which, for me, had a 100% drop rate of the Potent Mournbat Venom. The Venomous Mournbat's dropped zero for me.",
  "Wowhead050This quest has a wow classic drop rate vibe :)",
  "Wowhead050No, you're not doing it wrong. The droprate is bad.",
  "Wowhead050We are in YEAR 2026 and WHY blizzard still put MEGA low drop rate for quest items on RETAIL ? I wanted to read the whole questline, but instead it makes me want to skip everything.",
  "Wowhead050Incredibly low drop rate AND competing with a bunch of other players for slow respawns. Hard pass. Will come back in a few weeks when the zone is empty. This quest is such a bottleneck.",
  "Wowhead050Venom from bats? Srsly? You would thought it has to be collected from the big fat nasty spiders nearby. But no, bats who cant be poisonous. Blizz logic.",
},

[92023] = {
  "9202318080NPCUnknown0NPCUnknown00",
  "Wowhead050Vehn Sorrelstride says: Take care not to open it in an enclosed space. Those fumes will waken the dead . \"Foreshadowing is a literary device in wh-\" . Last edited by InsaneHacker on 2026/03/04 (Patch 12.0.1)",
  "Wowhead050The bottle of \"magister's reserve\" is bought from the same NPC where you turn in the quest.",
  "Wowhead050the items can be bought from the NPC's around the village",
  "Wowhead050They are all at ground level / way 40.6 60.16 last item and hand in / way 39.28 61 guy - on the ground / way 39.5 60.5 gal - on the ground",
  "Wowhead050Magister's Mead is at / way 40.71 60.09 as well as turn in for the quest",
},

