[92085] = {
  "9208518080NPCUnknown0NPCUnknown00",
  "Wowhead050The quest location looks like it's inside the cave, but the mount to fly is located up ground above near the pond by the stable master. As you progress you wind up back in the cave. Happy squishing! Last edited by ladywolfxo on 2026/03/06 (Patch 12.0.1)",
  "Wowhead050Ride the Lynx at 52.86, 52.29, outside.",
  "Wowhead050Half the time I get disconnected while mounting the Lynx.",
  "Wowhead050The creature you ride to squish the bugs is outside the cave but you eventually ride into the cave, no controls just guiding the mount , the bugs only appear once your on the mount",
  "Wowhead050They clearly dont need pest control because there barely any !@#$ing vermin",
  "Wowhead050To complete the quest Claw Enforcement , dismount from your own mount (to save being kicked - it's a known bug), mount the Swift Grimlynx at / way #2413 52.90 52.25 Swift Grimlynx above The Den , and run over 20 No Scurrying Vermin . The more you run over, the faster the mount will run. Coordinates for TomTom users: / way #2413 52.90 52.25 Swift Grimlynx above The Den Last edited by NessieMo 2 days ago (Patch 12.0.5)",
  "Wowhead050One of the MENSA members at Blizzard decided it was a good idea to make the Scurrying Vermin you have crush shared between all players. If you're running behind a player, change your path, or they'll gobble up all the vermin in front of you.",
},

[92121] = {
  "9212118080NPCUnknown0NPCUnknown00",
  "Wowhead050you can kill Enclave Lurker , clean nests and spiderwebs",
  "Wowhead050\"We love the outdoors, just not inside our strongholds\" *Builds a stronghold with no windows or doors, completely exposed to the elements*",
},

[92122] = {
  "9212218080NPCUnknown0NPCUnknown00",
  "Wowhead050The emberstrike mount is on the second floor of the building.",
  "Wowhead050please make the camera freaking stop. it's so ridiculous... my eyes want to throw up after 10 seconds.",
  "Wowhead050Is it me or does the mount have way too many sharp cuts, meaning your mouse goes from targeting a group needed for bombing, to not having any targets in it when you hitwhatever keybind you use for the bombing?",
  "Wowhead050During bombing, the dragonhawk flies waaaay too fast and need to slow down or just stop fidgeting PLEASE! It feels like if my grandfather was moving my mouse with a parkinsons hand. God bless his heart...",
  "Wowhead050Glad i'm not the only person who finds this WQ frustrating because it was clearly created in a hurry by someone who's never played the game.",
  "Wowhead050I find it much easier to target the drops if I face backward and target them after I've already passed over them.",
  "Wowhead050Fun fact - you can kill yourself on this quest if you drop the bomb right on the starting area immediately after mounting. Don't ask me how I know.",
},

[92138] = {
  "9213818080NPCUnknown0NPCUnknown00",
  "Wowhead050I had a dungeon queue pop while doing this and figured I'd finish this WQ after. But when I returned, I had no recruitment fliers and I couldn't pick them up from the original spot either, meaning I couldn't finish the WQ. So definitely do this one in it's entirety until they fix this bug.",
  "Wowhead050If you lose your papers, fly far away or to another zone. Then come back and approach from the ground, not by flying.",
  "Wowhead050I lost the flyers somehow and can't recruit people.",
  "Wowhead050Uh. . . what do the fliers look like? Im on top of a gold dot on mini map but don't see anything but a bench that is clickable.",
  "Wowhead050I found the papers at / way 41.02 15.63 ! WALK IN ! NO FLYING IN !",
},

[92139] = {
  "9213918080NPCUnknown0NPCUnknown00",
  "Wowhead050If you do not see Vilebranch Stalkers and altars to destroy, you are on the opening Zul'Aman campaign quests and need to complete them first. I had to complete from The Gates of Zul'Aman to Break the Blade before I could complete the Special Assignment in Eversong. If you haven't started the Zul'Aman campaign quests, this may not be an issue. Last edited by Meechakeecha on 2026/03/16 (Patch 12.0.1)",
  "Wowhead050If you have the Zul'Aman campaign quests chain started but not finished, you need to complete Break the Blade before you will be able to see the altars and the Vilebranch Stalker s needed for this quest. I found out this... the hard way.",
  "Wowhead050Broken. Locking any WQ behind the storyline - special assignment or not - is stupid. I've done the storyline on 2 toons leveled all the way to 90 (one horde and one alliance) and now I want to level my other toons partially through WQs but can't even access this one. And yes I've tried ALL the suggestions from all the other comments. Still can't get it. Ain't nobody got time for this level of idiocy, Blizz.",
  "Wowhead050I've done all WQs in Eversong and yet I still need to do one more to do unlock this WQ.....?",
  "Wowhead050You need to destroy an altar to see the stalkers.",
  "Wowhead050If you have completed the questline and still not see the altars or vilebranchers, or anything on your map; try going to [ / way 58, 79 ] inside the building you should be able to see a clickable altar. You need to click on the altar in order to phase where the vilebranchers and other altars \"actually\" are...",
  "Wowhead050I was not on that part of the campaign and had no issue. They did disappear because I also advanced the campaign while I was there.",
  "Wowhead050Because I had dropped the Amani quest line, I had to go back to the Visage of Jan'alai at 46: 45 to re-enable the quest line, and then finish it. Went back to the Shade and Claw quest site, and the altars showed up as gold dots.",
  "Wowhead050If you do not see Vilebranch Stalkers and altars you need to go to Silvermoon and talk to Soridormi first.",
  "Wowhead050Pretty screwy. I got the Special assignment, I was able to click all the altars for the quest and kill 4 of 8 of the Stalkers. Then they just stopped showing up. Seems people are having different problems with this quest. I'm doing the Campaign line now to see if the other 4 show up when I'm done.",
  "Wowhead050Special Assignment quests order: wed Harandar: A hunter's regret sat Eversong: Grand magister's drink wed Zul Aman: Ours once more! sat Voidstorm: Precision Excision wed Zul'Aman: What ramains of a tample broken. sat Harandar: Push back the light wed Voidstorm: Agents of the shield sat Eversong: Shade and Claw",
},

