[92180] = {
  "9218018080NPCUnknown0NPCUnknown00",
  "Wowhead050The elves are outside, not down in the basement as I thought.",
  "Wowhead050These quests are showing up for the second time on my toon.",
  "Wowhead050I guess the game acknowledges how much I like Astalor's style. It wants me to do these quests on the same character again.",
  "Wowhead050I have lots of alts, but it feels like i have to do this quest every week on main. Anyone else?",
  "Wowhead050omg he proposed to me!",
},

[92181] = {
  "9218118080NPCUnknown0NPCUnknown00",
  "Wowhead050After completing the previous quest ``Precious Jewels`` this one doesent pop up to me, am i doing something wrong?",
  "Wowhead050Had a problem where the Blood Elves wouldn't register after the cast, just keep running around and trying different ones and the ones you tried previously should start to work.",
  "Wowhead050Bugged for me TWICE. I completed it after getting renown 4, a few days ago, and today, had the first quest in the quest chain with Alastor. Did them all, got to this, and once again, the big coalesded things don't register credit. Doing what I did first time and dropping it and picking it up again...",
  "Wowhead050While attempting this quest i had to drop my current Prey hunt. Also, as i was on my shaman, i wasn't receiving credit while in wolf form . / shrug",
},

