[92429] = {
  "9242918080NPCUnknown0NPCUnknown00",
  "Wowhead050If you're here hoping that surely Blizzard doesn't expect us to this 1% at time... good news! They don't. Make sure to kill the highlighted yellow mobs: deer, boar, doe, etc. Then use the Biological Vacuum to suck off the flesh. Easy. If you're quick, you can double tap the same carcass twice. Last edited by Hopsea on 2026/02/15 (Patch 12.0.1)",
  "Wowhead050If you're a Druid, use Entangling Roots to keep the mob in place then use the item provided to finish the quest. Easy and quick!",
  "Wowhead050I somehow didn't receive the vacuum upon accepting this quest. I DID, in fact, think that Blizzard was making me kill 100 mobs! After reading the comments, I deleted the quest and reacquired it. Much easier with the vacuum!",
  "Wowhead050Do not kill the animals. Use the item in your bag, Biological Vacuum, which will cast a cone in front of you while slowing you down. Use near highlighted animals. Last edited by Lovestorybro yesterday at 5:21 PM (Patch 12.0.5)",
},

[92430] = {
