[92713] = {
  "9271318080NPCUnknown0NPCUnknown00",
  "Wowhead050Okay so what is the fastest relic to bang out the weekly? EDIT: The Root of the World is literally 2 minutes with no combat, pick that one. Last edited by hashey 27 days ago (Patch 12.0.5)",
