[93049] = {
  "9304918080NPCUnknown0NPCUnknown00",
  "Wowhead050Starts from An'jali at / way #2437 46.65 68.00 An'jali Homework Support . Part of the Beyond the Walls storyline. Pristine Shade Lily is found in the shade - beneath bridges, houses and roofs: / way #2437 42.55 66.77 Shade Lily Cluster / way #2437 44.28 67.79 Shade Lily Cluster / way #2437 42.85 69.85 Shade Lily Cluster / way #2437 46.70 66.86 Shade Lily Cluster / way #2437 46.90 66.65 Shade Lily Cluster / way #2437 46.90 65.98 Shade Lily Cluster / way #2437 46.76 66.20 Shade Lily Cluster Last edited by Ooshraxa on 2025/11/17 (Patch 11.2.5)",
  "Wowhead050There are several of the shade lilies under the Amani Quartermaster building. Last edited by Hildur on 2026/02/28 (Patch 12.0.1)",
  "Wowhead050Look under the buildings that have their foundations on pillars. There are at least two, and the lilies are found under the buildings.",
},

[93050] = {
  "9305018080NPCUnknown0NPCUnknown00",
  "Wowhead050Go to 43, 68 to pick up the quest",
  "Wowhead050HOW? The actual altar is OUTSIDE behind the altar you're trying to figure out. It's literally right next to Du'gal. Last edited by Malvenue on 2026/03/05 (Patch 12.0.1)",
  "Wowhead050I've completed the entire campaign and am level 90. I am now doing the sojourner quests and am stuck on this quest. I've done the first three quests in the Beyond the Walls segment of the Zul Aman sojourner, but the NPC that's supposed to have this quest isn't showing it. Has anyone else had this issue? It's the last set I need for the achievement.",
  "Wowhead050Correct coordinates are 43.51 68.87.",
  "Wowhead050Rakan isn't there, so can't pickup quest? Homework Support is completed..",
  "Wowhead050I had a problem with this quest to get the Sojourner achievement - did it on my alt, and for some reason it didn't count towards the achievement, although it was marked as warband completed - had to do it again on my main.",
  "Wowhead050This appears to unlock once the chapter Loa of Murlocs is complete. It opened up around the same time I was able to start choosing loa to worship. Last edited by Arrokoth on 2026/03/18 (Patch 12.0.1)",
  "Wowhead050If the NPC cannot be found at the coordinates here in the comments, you have completed The Final Exam The Final Exam. That quest comes after this one and can, somehow, be picked up and completed before this one.",
},

[93051] = {
  "9305118080NPCUnknown0NPCUnknown00",
  "Wowhead050This quest requires Level 3 Renown with the Amani Tribe before it shows up.",
  "Wowhead050Started by Recruit Dar'rak at / way #2437 43.18 67.12 The Final Exam Part of the Beyond the Walls storyline.",
  "Wowhead050Dialogue if you allow the recruit to kill you: Recruit Dar'rak: \"Wait, no! I'm so sorry, I didn't mean to--\" Ri'Kari: \"Recruit! Dis challenge was about knowin' restraint, not just brute strength.\" Ri'Kari: \"Try again once de champion regains their strength.\" Last edited by CyanideWow on 2026/03/11 (Patch 12.0.1)",
  "Wowhead050Be careful if you have any fragile pets (like a mage's Mirror Images). If he kills one, it counts as you losing and you'll have to retrigger the fight.",
},

