[93385] = {
  "9338518080NPCUnknown0NPCUnknown00",
  "Wowhead050/ run for all to see which you have and have not done: / run local q,n={93372,93384,93385,93386,93409,93410,93416,93421,93427,93428},{\"Encl\",\"Coll\",\"Dark\",\"Plaz\",\"Atal\",\"Twil\",\"Gulf\",\"Grud\",\"Sunk\",\"Shad\"}for i,v in ipairs(q)do print(n[i],C_QuestLog.IsQuestFlaggedCompleted(v)and\"OK\"or\"NO\")end Delver's Quest Pickup Coords (Click to Copy) Delve Entrance (Click to Copy) Zone Collegiate Calamity / way 41, 61 / way 40.76, 54.06 Silvermoon City The Darkway ? / way 39.3, 32.1 Silvermoon City Shadow Enclave / way 50, 40 / way 45.4, 86.0 Eversong Woods Atal'Aman In delve / way 24.8, 53.0 Zul'Aman Twilight Crypts / way 43, 67 / way 25.4, 84.3 Zul'Aman The Grudge Pit / way 71, 52 / way 70.5, 64.9 Harandar The Gulf of Memory / way 52, 51 / way 36.3, 49.2 Harandar Sunkiller Sanctum / way 42, 70 / way 54.8, 47.0 Voidstorm Shadowguard Point / way 37, 51 / way 37.38, 47.7 Voidstorm Parhelion Plaza ? / way 47.74, 41.58 Isle of Quel'Danas Last edited by Smaktat on 2026/03/02 (Patch 12.0.1)",
  "Wowhead050And, oh yeah, by the way, it does not open until March 24, 2026. (:",
  "Wowhead050The quest pickup, besides inside the delve itself, is on the wall of the entrance of the Delves HQ in Silvermoon City. / way #2393 52.23 78.00",
  "Wowhead050Here is improved macro that will show if you have the delve quest completed in your log OR if you have returned the quest already. It shows the title of the quest/ delve and color coordinated completed vs not. / run local l,q=C_QuestLog,{93372,93384,93385,93409,93410,93416,93421,93427,93428,93386}for i,v in ipairs(q)do print((l.IsQuestFlaggedCompleted(v)or l.IsComplete(v))and\"\\124c0000FF00\"or\"\\124c11FF1100\",l.GetTitleForQuestID(v),\"\\124r\")end https:// i.imgur.com/ rwtslGm.png",
  "Wowhead050The quest is inside the delve.",
  "Wowhead050Since there's little to no info about the actual mechanics, I'll add some here. To \"Install\" the Ley Line Focusers, I had already gotten my 6 (There are many more). I just ran through them. The ores seem to be marked on the map as sturdy chests. I found no chests at all. I wasn't able to unlock any Locked Doors, but they may be for a higher lvl in this delve. Wuss here, so tried it first time on lvl 3.",
  "Wowhead050This Delve will become active on the week of March 17, with the release of Midnight Season 1.",
  "Wowhead050Delver's Call - Midnight Locations: Eversong Woods / way #2393 41.8 61.4 Collegiate Clamity / way #2393 52.5 77.9 Parhelion Plaza / way #2395 50.8 40.0 The Shadow Enclave / way #2393 52.2 78.0 The Darkway Zul'Aman / way #2437 24.8 53.0 Atal'Aman (In Delve) / way #2437 43.7 67.3 Twilight Crypts Harandar / way #2413 71.1 52.1 The Grudge Pit / way #2413 52.8 51.7 The Gulf of Memory Voidstorm / way #2405 37.6 51.9 Shadowguard Point / way #2405 42.7 70.7 Sunkiller Sanctum",
},

[93386] = {
  "9338618080NPCUnknown0NPCUnknown00",
  "Wowhead050This Delve will become active on the week of March 31, with the release of the March on Quel'Danas raid. Last edited by Drelnar on 2026/03/03 (Patch 12.0.1)",
  "Wowhead050/ run for all to see which you have and have not done: / run local q,n={93372,93384,93385,93386,93409,93410,93416,93421,93427,93428},{\"Encl\",\"Coll\",\"Dark\",\"Plaz\",\"Atal\",\"Twil\",\"Gulf\",\"Grud\",\"Sunk\",\"Shad\"}for i,v in ipairs(q)do print(n[i],C_QuestLog.IsQuestFlaggedCompleted(v)and\"OK\"or\"NO\")end Delver's Quest Pickup Coords (Click to Copy) Delve Entrance (Click to Copy) Zone Collegiate Calamity / way 41, 61 / way 40.76, 54.06 Silvermoon City The Darkway ? / way 39.3, 32.1 Silvermoon City Shadow Enclave / way 50, 40 / way 45.4, 86.0 Eversong Woods Atal'Aman In delve / way 24.8, 53.0 Zul'Aman Twilight Crypts / way 43, 67 / way 25.4, 84.3 Zul'Aman The Grudge Pit / way 71, 52 / way 70.5, 64.9 Harandar The Gulf of Memory / way 52, 51 / way 36.3, 49.2 Harandar Sunkiller Sanctum / way 42, 70 / way 54.8, 47.0 Voidstorm Shadowguard Point / way 37, 51 / way 37.38, 47.7 Voidstorm Parhelion Plaza ? / way 47.74, 41.58 Isle of Quel'Danas Last edited by Smaktat on 2026/03/02 (Patch 12.0.1)",
  "Wowhead050The entrance to the spire where the delve is located is \" / way #2424 47.72 41.55 Isle of Quel'Danas \". Also, watch out for patrolling mobs when you come out. Last edited by Tulabear on 2026/03/31 (Patch 12.0.1)",
  "Wowhead050Has anyone found the entrance for this?",
  "Wowhead050It's April 3. Why am I dying trying to get to this delve entrance?",
  "Wowhead050Here is improved macro that will show if you have the delve quest completed in your log OR if you have returned the quest already. It shows the title of the quest/ delve and color coordinated completed vs not. / run local l,q=C_QuestLog,{93372,93384,93385,93409,93410,93416,93421,93427,93428,93386}for i,v in ipairs(q)do print((l.IsQuestFlaggedCompleted(v)or l.IsComplete(v))and\"\\124c0000FF00\"or\"\\124c11FF1100\",l.GetTitleForQuestID(v),\"\\124r\")end https:// i.imgur.com/ rwtslGm.png",
  "Wowhead050As you run into the spire as shown on the map, (there are two priests just outside). There is a ramp on the left leading down to the entrance. I ran in there about 3-4 times before I noticed the ramp, it just looks like part of the floor pattern. (Just to state the bleeding obvious - this is not the ramp in the main big spire leading down to the Sun Well)",
  "Wowhead050You can pick up this quest at the entrance of Delver's Headquarters in Silvermoon City",
  "Wowhead050If its not a bug, the 3 adds of the boss are a menace they really need to go very fast or else its a guarantee wipe and thats on tier 11 not sure about lower tiers tho",
  "Wowhead050This can be a confusing delve the first time through so use your main map, not the mini-map, to figure out where to go to destroy the portals. 2nd, you don't have to carry around the bomb devices; they're all over the place.",
  "Wowhead050Don't bother as a dps. The boss adds will just kill you outright. Their scaling is completely bugged. They two-shot a valeria tank, one shot hunter pets and two shot you. Just wasted a map and way too much time trying to kill it at 255. Guildies told me that they could do it with a tank specced character but difficult/ not as anything else. Last edited by Reii 12 days ago (Patch 12.0.5)",
  "Wowhead050Delver's Call - Midnight Locations: Eversong Woods / way #2393 41.8 61.4 Collegiate Clamity / way #2393 52.5 77.9 Parhelion Plaza / way #2395 50.8 40.0 The Shadow Enclave / way #2393 52.2 78.0 The Darkway Zul'Aman / way #2437 24.8 53.0 Atal'Aman (In Delve) / way #2437 43.7 67.3 Twilight Crypts Harandar / way #2413 71.1 52.1 The Grudge Pit / way #2413 52.8 51.7 The Gulf of Memory Voidstorm / way #2405 37.6 51.9 Shadowguard Point / way #2405 42.7 70.7 Sunkiller Sanctum",
},

