[93766] = {
  "9376618080NPCUnknown0NPCUnknown00",
  "Wowhead050I just completed this and it gave just shy of 18k. Is that supposed to be how it works? See the screencap that I submitted.",
  "Wowhead050Why do \"World Quests\" inside SilverMoon NOT accrue as World Quests on Hope in the Darkest Corners.... Please fix, either they are NOT world quests, fix symbol or they ARE so fix accrue. Thank you",
},

[93767] = {
  "9376718080NPCUnknown0NPCUnknown00",
  "Wowhead050The bartender sells an item called a Toasting Brew and you have to target another player. Really easy if there are people in the arcantina",
  "Wowhead050You can toast with the Toasting Brew (Bought from the Bartender) while targeting yourself. This will likely get fixed, but as of right now it works! Last edited by PorkyDaTongan on 2026/03/07 (Patch 12.0.1)",
  "Wowhead050Did you pick the weekly quest for the Arcantina? Super quick to complete, all you have to do is Toast 3 players. Here is a quick explanation on how to toast and quickly complete! First- start by heading to the arcantina - either the portal in the inn, or the toy \"Personal Key to the arcantina\" Portal in Silvermoon is / way 55.92, 70.62 Next, take a right as you zone in and speak to the bartender named Bob and purchase 3x Toasting Brew (10silver each) then target another player (not NPC) and use the item. Repeat another 2 times and complete the quest. Walk back out the portal to Silvermoon city and turn in the quest! Here is a quick video for completion: https:// youtu.be/ AUBwJ4MwgMY",
  "Wowhead050If, like me, you weren't paying attention during questing: You access the Arcantina via a portal created by the Personal Key to the Arcantina toy.",
  "Wowhead050Sooo... maybe this is just me, but I think the most important part of toasting with other players is to actually HAVE OTHER PLAYERS PRESENT. This place is empty all the time. Ugh.",
  "Wowhead050Once you buy x3 Toasting Brew from the Bartender you can target yourself and use the item.",
},

[93769] = {
  "9376918080NPCUnknown0NPCUnknown00",
  "Wowhead050Completing and turning in the weekly warbound (only 1 character per week per account) quest from Vaeli , such as Community Engagement , completes this quest as Vaeli 's quest rewards you with the requisite Community Coupons . Vaeli is just to the right of the tent from where you picked up this quest. Last edited by Aisenfaire on 2026/04/14 (Patch 12.0.1)",
},

