[93850] = {
  "9385018080NPCUnknown0NPCUnknown00",
  "Wowhead050You must queue the follower dungeon to Quell the Spirits",
  "Wowhead050In order to complete this queue up for the Windrunner Spire dungeon follower, normal, or heroic (did not try mythic 0) and kill the last boss the restless heart and the quest will be ready for turn-in!",
  "Wowhead050i need a downvote from everyone who didn't know they had to do the dungeon for the quest",
  "Wowhead050To get this quest, you must progress the Campaign. I believe I unlocked it as soon as I finished 13. Silvermoon Must Know - which is the questline 'Whispers in the Twilight'.",
  "Wowhead050You have to que for the dungeon for the quest.",
},

[93865] = {
  "9386518080NPCUnknown0NPCUnknown00",
  "Wowhead050When you pick-up the quest it applies a debuff called 'Azerothian Preference' which prevents you from duelling the Masters' Champion until it expires. You can either wait it out and duel the champion or duel other players to complete the quest.",
  "Wowhead050You don't need to wait in the safe zone/ \"city\" for the debuff to drop. Get the quest, do the world quests in the zone and do this one at the end. The debuff is long gone at this point and you can duell him directly without waiting.",
  "Wowhead050Find the Masters' Champion down in the pit. Stand next to him (within 5 yards) and use your Quest Item \"Domanaar Dueling Flag\" that is in your bag (or on your Quest Menu). Beat him, and turn in. - Win -",
  "Wowhead050You need to have warmode on. Go to Ziadan to turn it on/ off. / way #34.77 80.35 Ziadan",
},

