[94677] = {
  "9467718080NPCUnknown0NPCUnknown00",
  "Wowhead050first is marked - in building behind quest building, second and third were not for me: / way 32.98 65.05 # / way 30.45 67.49",
  "Wowhead050Even after you collect the first one, the others don't appear until after a minute or three. Disappointing, 17 chapters apparently isn't enough to require too many hours to level, but there is a delay before these things spawn. Apparently the quest writers have run out of ideas.",
  "Wowhead050After you finish this quest all three items remain in your inventory. Deleting them is fine.",
  "Wowhead050You have to collect them in order, so you won't see the other ones until you get the ones before",
  "Wowhead050You MUST loot these in order. Here are all the locations in order / way #2413 30.96 64.71 Musing Part 1 / way #2413 32.96 65.06 Musing Part 2 / way #2413 30.45 67.52 Musing Part 3 The Part 1 is in a chest, the 2nd and 3rd are scrolls on the ground. Last edited by ViddWizard on 2026/03/29 (Patch 12.0.1)",
  "Wowhead050The last one for me was on a platform overlooking the water. If that helps anyone else find it. It has npcs standing around.",
  "Wowhead050The first clue is in the building directly behind the quest giver. Go up the 7 stairs and your in. The first note will be marked on your minimap",
  "Wowhead050I encountered a bug where, even though I had collected all 3 notes, my quest tracker only said '2/ 3' collected. Relogging and then re-looting the last item fixed it.",
  "Wowhead050When you submit screenshots please zoom out so we can see the surrounding area.",
  "Wowhead050I like how the second Musings, he claims \"certainly\" which forshadows him would later engulfs him into light from Lightbloom, third 3 giving more clearer hint of betrayal that would later happen.",
  "Wowhead050This is a whole new level of stupidity. Apparently the items are not just there to be found. Either they're on some type of timer or they must be found in order, because the third one absolutely appeared in a spot I had already checked. Not only is this annoying and a waste of time, it doesn't make sense with the quest text.",
},

[94743] = {
  "9474318080NPCUnknown0NPCUnknown00",
  "Wowhead050No parsed comments available yet. Wowhead URL: https://www.wowhead.com/quest=94743",
},

[94790] = {
  "9479018080NPCUnknown0NPCUnknown00",
  "Wowhead050Even though I've maxed out the console with 7 Uncontaminated Void Samples, this quest is still available and rewards another one (also a bit of gold). Might as well do it if you are planning on completing WQs in Voidstorm I guess.",
  "Wowhead050Note that any PvP World Quests in Slayer's Rise (such as Elemental Dominance or Undercover Hunt ) do NOT count towards this quest. Any regular non-PvP world quests in Slayer's Rise do count.",
  "Wowhead050Half of the world quests don't seem to count towards this quest. Reported it.",
  "Wowhead050Question mark for handing in quest is faded to indicate that it is underground: it's not, it's above ground.",
  "Wowhead050How do you reset the points spent in the console?",
  "Wowhead050As of March 19 the Prey WQ does not count towards progress for this quest.",
  "Wowhead050It has to be 3 world quests, not weekly quests. If that wasn't reading before, it's fixed now, but make sure you aren't doing weekly repeatable quests at stormarion.",
  "Wowhead050I came back here to locate the actual console and did not find it here. Just in case you came here for the same reason you can find the console at / way 52.61, 72.85 in Voidstorm on Howling Ridge, a little SE of the Silvermoon and Harandar portals .",
  "Wowhead050What do you do with the extra Void Research Points. I filled the seven slots, and have 4 more. Any ideas?",
},

