[95843] = {
  "9584318080NPCUnknown0NPCUnknown00",
  "Wowhead050Only one Ritual Site is available each week, so to complete this weekly meta quest in the same week as we pick it up we'd have to do the same scenario 3 times? Not a very alluring prospect to me if I'm being honest Considering that one of the weekly meta quests is super easy and consists of us drinking with 3 other players in the Arcantina, demanding we do 3 Ritual Sites for this one makes no sense",
},

[96242] = {
  "9624218080NPCUnknown0NPCUnknown00",
  "Wowhead050Open: Group Finder > Player vs. Player > Decor Duel and hit Join Battle .",
  "Wowhead050Turn-in at 31.52, 76.62",
  "Wowhead050yes, im also here because of the typo \"If there's a GROUP you wan to FIND\"",
